from collections import Counter

def transform(grid):
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    out_h, out_w = 3, 3

    # Calculate region boundaries for rows and columns
    row_regions = []
    for i in range(out_h):
        start = i * (h // out_h)
        remainder = h % out_h
        # Later regions get the extra rows
        end = start + (h // out_h) + (1 if i >= remainder else 0)
        row_regions.append((start, end))

    col_regions = []
    for i in range(out_w):
        start = i * (w // out_w)
        remainder = w % out_w
        end = start + (w // out_w) + (1 if i >= remainder else 0)
        col_regions.append((start, end))

    result = []
    for r in range(out_h):
        row_vals = []
        for c in range(out_w):
            r_start, r_end = row_regions[r]
            c_start, c_end = col_regions[c]

            vals = []
            for i in range(r_start, min(r_end, h)):
                for j in range(c_start, min(c_end, w)):
                    vals.append(grid[i][j])

            if vals:
                val, _ = Counter(vals).most_common(1)[0]
                row_vals.append(val)
            else:
                row_vals.append(0)
        result.append(row_vals)

    return result
